
# --- portable paths (generated by export) -------------------------
# Everything below derives from the repo location; override with env vars
#   COMFYUI_DIR / COMFY_PYTHON / FOUNDRY_PYTHON
$FF_ROOT = if ($PSScriptRoot -and (Test-Path (Join-Path $PSScriptRoot 'app.py'))) {
    $PSScriptRoot
} else {
    Split-Path -Parent $PSScriptRoot
}
$FF_COMFY = if ($env:COMFYUI_DIR) { $env:COMFYUI_DIR } else { Join-Path (Split-Path -Parent $FF_ROOT) 'ComfyUI' }
$FF_COMFY_PY = if ($env:COMFY_PYTHON) { $env:COMFY_PYTHON } else { Join-Path $FF_COMFY 'python.exe' }
$FF_APP_PY = if ($env:FOUNDRY_PYTHON) { $env:FOUNDRY_PYTHON } else { 'python' }
$FF_LOG = Join-Path $FF_ROOT 'logs'
if (-not (Test-Path $FF_LOG)) { New-Item -ItemType Directory -Force -Path $FF_LOG | Out-Null }
# ------------------------------------------------------------------
# GPU 温度调节器 · 管理员一次性安装（右键 → 以管理员身份运行）
# 作用：注册开机自启计划任务 DSH-ThermalGovernor（最高权限），
#       让 thermal_governor.py 持续按 81°C 起逐步降频 / 77°C 恢复。
$ErrorActionPreference = "Stop"

Write-Host "=== 安装 GPU 温度调节器（需要管理员）===" -ForegroundColor Cyan

# 1. 权限自检
$test = nvidia-smi -lgc 210,2100 2>&1 | Out-String
if ($test -match "permission") {
    Write-Host "❌ 当前未提权。请右键本脚本 → 以管理员身份运行。" -ForegroundColor Red
    exit 1
}
nvidia-smi -rgc 2>$null
Write-Host "✅ 时钟控制权限正常（可降频）" -ForegroundColor Green

# 2. 校验文件
if (-not (Test-Path (Join-Path $FF_ROOT 'scripts\thermal_governor.cmd'))) {
    Write-Host "❌ 找不到 thermal_governor.cmd" -ForegroundColor Red
    exit 1
}

# 3. 注册开机自启计划任务（onlogon + 最高权限）
schtasks /create /tn "DSH-ThermalGovernor" `
    /tr (Join-Path $FF_ROOT 'scripts\thermal_governor.cmd') `
    /sc onlogon /rl highest /f | Out-Null
if ($LASTEXITCODE -ne 0) {
    Write-Host "❌ 计划任务创建失败" -ForegroundColor Red
    exit 1
}
Write-Host "✅ 已注册开机自启: DSH-ThermalGovernor（onlogon, 最高权限）" -ForegroundColor Green

# 4. 立即启动一次
Start-Process -FilePath (Join-Path $FF_ROOT 'scripts\thermal_governor.cmd') -WindowStyle Hidden
Write-Host "✅ 调节器已启动（日志: $FF_LOG\thermal_governor.log）" -ForegroundColor Green
Write-Host ""
Write-Host "完成。之后每次登录都会自动运行温度调节器。" -ForegroundColor Cyan
